namespace ArtifactX.WinUI3.ViewModels;

/// <summary>
/// The space station on the system map, in thousands of units like <see cref="SystemMapBody"/>: generated by
/// <c>StationPoseGeneration</c> (exact against 100 emulator poses, 2026-10-25). Its system space matches the save's
/// planet centres: the generated centres round down to the save's in four save systems checked 2026-10-27.
/// </summary>
public sealed record SystemMapStation(string Name, double X, double Y, double Z);
